"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4598],{5715(e){e.exports=JSON.parse('{"title":"React\ub294 \ud558\ub098\uc758 \uc5b8\uc5b4\ub2e4.","date":"2024-11-22","coverUrl":null,"html":"<h2 data-notion-block-id=\\"142e548d-8a8e-80f3-9b22-c7a0a0f6a0bf\\" id=\\"142e548d-8a8e-80f3-9b22-c7a0a0f6a0bf\\">React\ub294 \ud558\ub098\uc758 \uc5b8\uc5b4\ub2e4.</h2><a href=\\"https://buildui.com/posts/react-is-a-programming-language-and-its-rules-are-its-syntax\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://buildui.com/posts/react-is-a-programming-language-and-its-rules-are-its-syntax</a><p data-notion-block-id=\\"142e548d-8a8e-802a-9e9e-ec292c5478f0\\"><b>\uc2ec\uc724\uc12d</b>: React\uc5d0\uc11c\ub294 <a href=\\"https://react.dev/reference/react#rules-of-react\\">\uc5ec\ub7ec\uac00\uc9c0 \uaddc\uce59</a>(\uc554\ubb35\uc801\uc778 \uaddc\uce59\uc744 \ud3ec\ud568\ud574\uc11c)\uc744 \uac16\uace0 \uc788\uace0, \uc774\ub294 \ubc14\ub2d0\ub77c JS\uc640\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ucf54\ub4dc\ub97c \ub9cc\ub4e4\uae30\ub97c \uc720\ub3c4\ud569\ub2c8\ub2e4. \uae00\uc4f4\uc774\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac/\ud504\ub808\uc784\uc6cc\ud06c\ub97c \uac00\uc7a5 \uc798 \uc4f0\ub294 \ubc29\ubc95\uc740 \uba54\uc778\ud14c\uc774\ub108\uac00 \ud558\uace0\uc790 \ud55c \uac83, \uc0dd\uac01\ud55c \uac83\uc744 \ub530\ub77c\uac00 \ubcf4\ub294 \uac83\uc774\ub77c\uace0 \uc8fc\uc7a5\ud558\uace0, \uc800\ub3c4 \uadf8\ub807\uac8c \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub354 \ub098\uc544\uac00\uc11c \ub77c\uc774\ube0c\ub7ec\ub9ac/\ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc0ac\uc6a9\ud558\uae30 \uc804\uc5d0 \uc801\uc5b4\ub3c4 \ud575\uc2ec concept\ub098 \uc6d0\uce59, \ud574\uacb0\ud558\uace0\uc790 \ud55c \ubb38\uc81c, \ud06c\uac8c\ub294 \ubb38\uc11c \uc804\uccb4\ub97c \ubd10\uc57c \ub77c\uc774\ube0c\ub7ec\ub9ac/\ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc0ac\uc6a9\ud55c \uc758\ubbf8\uac00 \uc0dd\uae34\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. JS\uc640 JS \uc0dd\ud0dc\uacc4\ub294 \uc801\uc740 \uc81c\uc57d\uc73c\ub85c \ub2e4\uc591\ud55c \ubc29\uc2dd\uc73c\ub85c \ucf54\ub4dc\ub97c \ub9cc\ub4e4 \uc218 \uc788\uac8c \ud558\uc9c0\ub9cc, \uaddc\uce59\uc774\ub098 \uc81c\uc57d\uc744 \ub530\ub974\uc9c0 \uc54a\uc73c\uba74 \uc5b4\uca4c\uba74 AI\ubcf4\ub2e4 \uc0dd\uc0b0\uc131\uc774 \ub0ae\uc544\uc9c8 \uc218\ub3c4 \uc788\ub2e4\uace0\ub3c4 \ub5a0\uc624\ub974\uac8c \ub418\ub124\uc694.</p><p data-notion-block-id=\\"74411d2c-68ff-4843-af77-2525107c0227\\"><b>\uae40\ub300\uad00</b>: \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \ud504\ub808\uc784\uc6cc\ud06c\ub294 \ud2b9\uc815 \uae30\uc220\uc801 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774\ub97c \uc120\ud0dd\ud560 \ub54c\ub294 \uc790\uc2e0\uc774 \ud574\uacb0\ud558\ub824\ub294 \ubb38\uc81c\uc640 \ud574\ub2f9 \ub3c4\uad6c\uac00 \ud574\uacb0\ud558\ub824\ub294 \ubb38\uc81c\uac00 \uc77c\uce58\ud558\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. React \uc5ed\uc2dc \ubb38\uc81c \ud574\uacb0\uc744 \uc704\ud55c \ud328\ud134\uacfc \uae30\ub2a5\uc5d0 \uae30\ubc18\ud55c \uaddc\uce59\ub4e4\uc774 \uc788\uc73c\uba70, \uc774\ub97c \ub530\ub974\ub294 \ubc29\uc2dd\uc774 \ud558\ub098\uc758 \uc5b8\uc5b4\ucc98\ub7fc \ub290\uaef4\uc9c0\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc81c\uc57d\ubcf4\ub2e4\ub294 \uaddc\uce59\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \ud558\ub098\uc758 \uc5b8\uc5b4\ub77c\ub294 \uac83\uc5d0 \uc800\ub3c4 \ub3d9\uc758\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"142e548d-8a8e-80e4-b9c5-e63e91237932\\" id=\\"142e548d-8a8e-80e4-b9c5-e63e91237932\\">\ud558\ub098\uc758 \ud568\uc218\uc5d0 \ud558\ub098\uc758 \ub3d9\uc791.</h2><a href=\\"https://www.tymzap.com/blog/the-magic-of-keeping-one-abstraction-level-per-function\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.tymzap.com/blog/the-magic-of-keeping-one-abstraction-level-per-function</a><p data-notion-block-id=\\"142e548d-8a8e-80df-bf14-c29113d37001\\"><b>\uc2ec\uc724\uc12d</b>: (\uae00\uc5d0\ub294 \uc801\ud600\uc788\uc9c0 \uc54a\uc9c0\ub9cc) SOLID \uc6d0\uce59\uc758 \ub2e8\uc77c \ucc45\uc784 \uc6d0\uce59(SRP)\ub97c React\uc640 JS \uae30\ubc18\uc73c\ub85c \uac04\ub2e8\ud558\uac8c \uc124\uba85\ud55c \uae00\uc785\ub2c8\ub2e4. \ud558\ub098\uc758 \ub3d9\uc791\uc744 \uc815\uc758\ud558\ub294 \uac83\uc744 \uc790\uc8fc \uc0dd\uac01\ud574\ubcf4\uba74 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \uacbd\uc6b0\uc5d0 \ub530\ub77c\uc11c \uae00\uc5d0 \uc801\ud78c \uc774\uc810\uc774 \ub4dc\ub7ec\ub0a0 \ub54c\ub3c4 \uc788\uc9c0\ub9cc, \uacbd\uc6b0\uc5d0 \ub530\ub77c <a href=\\"https://atomicdesign.bradfrost.com/chapter-2/\\">Atomic Design</a>\uac19\uc774 \ub108\ubb34 \ub9ce\uc774 \ucabc\uac1c\uc838\uc11c \ub514\ubc84\uae45\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4(Atomic Design\uc774 \ub098\uc05c \ucd94\uc0c1\ud654\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uad00\ub9ac\ud558\ub294 \uc0ac\ub78c\uc774 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4\uba74 \uc88b\uc740 \ucd94\uc0c1\ud654\ub77c\uace0 \ubcf4\uae30 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4).</p><h2 data-notion-block-id=\\"141e548d-8a8e-8048-81ae-ccab5352fca9\\" id=\\"141e548d-8a8e-8048-81ae-ccab5352fca9\\">\uc81c\uc5b4 \ucef4\ud3ec\ub10c\ud2b8\uc640 \ube44\uc81c\uc5b4 \ucef4\ud3ec\ub10c\ud2b8, \uadf8\ub9ac\uace0 \uad00\uc810</h2><a href=\\"https://buildui.com/posts/uncontrolled-vs-controlled-a-matter-of-perspective\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://buildui.com/posts/uncontrolled-vs-controlled-a-matter-of-perspective</a><p data-notion-block-id=\\"142e548d-8a8e-80b0-961b-fa1e3a4211b1\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://react.dev/learn/sharing-state-between-components#controlled-and-uncontrolled-components\\">React \uacf5\uc2dd\ubb38\uc11c\uc5d0\ub3c4 \uc801\ud600\uc788\ub4ef\uc774</a>, <code>useState</code>\ub97c \uc0ac\uc6a9\ud558\uba74 \uc81c\uc5b4 \ucef4\ud3ec\ub10c\ud2b8, <code>useRef</code>\ub97c \uc0ac\uc6a9\ud558\uba74 \ube44\uc81c\uc5b4 \ucef4\ud3ec\ub10c\ud2b8\ub77c\uace0 \uc18c\uac1c\ud558\uc9c0 \uc54a\uace0, \uc0c1\ud669\uc5d0 \ub530\ub77c \uc81c\uc5b4 \ud639\uc740 \ube44\uc81c\uc5b4 \ubc29\uc2dd\uc73c\ub85c \uc0c1\ud0dc \uad00\ub9ac\ub97c \ud55c\ub2e4\uace0 \uc801\ud600\uc788\uc2b5\ub2c8\ub2e4(\ub2e4\uc18c \uc758\uc5ed). React-Hook-Forms\uc640 \uac19\uc774 \ub450 \ubc29\uc2dd\uc744 \ud63c\ud569\ud574\uc11c \uc0ac\uc6a9\ud560 \uc218\ub3c4 \uc788\uace0, \uc678\ubd80 \ucef4\ud3ec\ub10c\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud574\uc11c \uae00\uc5d0\uc11c \uc81c\uc2dc\ud558\ub294 \ud63c\ud569\ub41c \uc0c1\ud0dc\ub97c \ucee8\ud2b8\ub864\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uac04\ub2e8\ud55c \uae00\uc774\uc9c0\ub9cc, \uc81c\uc5b4/\ube44\uc81c\uc5b4\ub97c \uc5b4\ub5bb\uac8c \ub2e4\ub8e8\uc5b4\uc57c \ud558\ub294\uc9c0 \uc798 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"142e548d-8a8e-80e3-88f3-da44da34894e\\" id=\\"142e548d-8a8e-80e3-88f3-da44da34894e\\">\uac00\uc6b4\ub370 \uc815\ub82c\ud588\ub2e4\uace0 \uc815\ub9d0 \uac00\uc6b4\ub370\uc778\uac00\uc694?</h2><a href=\\"https://fullystacked.net/centering-things/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fullystacked.net/centering-things/</a><p data-notion-block-id=\\"142e548d-8a8e-80b3-8607-c881c3e51a57\\">\uc608\uc804 \uae00\uc778 <a href=\\"https://ones-to-watch.ethansup.net/news/post/022fc2c2-88d3-4c20-9075-defdea8ae65c#9399469d-45ed-4d8a-a6eb-1bf793278b51\\">\uac00\uc6b4\ub370 \uc815\ub82c\uc740 \ud798\ub4e4\ub2e4</a>\uc5d0\uc11c \ub9d0\ud588\ub4ef\uc774 \uc9c4\uc9dc \uac00\uc6b4\ub370 \uc815\ub82c\uc744 \ucc3e\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uac00\uc6b4\ub370 \uc815\ub82c\ud558\uae30\uc5d0 \uad00\ub828\ub41c \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc778 block\uc5d0\uc11c <code>align-content</code>\uc0ac\uc6a9\uc774\ub098 <code>fit-content</code>, <code>text-box-*</code>\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"142e548d-8a8e-8078-b8ce-c60961dbae9a\\" id=\\"142e548d-8a8e-8078-b8ce-c60961dbae9a\\">\uba74\uc811 \ub2e8\uace8\uc9c8\ubb38: \ube0c\ub77c\uc6b0\uc800\uc5d0 URL\uc744 \uc785\ub825\ud558\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc77c\uc5b4\ub098\ub098\uc694?</h2><a href=\\"https://abhisaha.com/blog/exploring-browser-rendering-process\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://abhisaha.com/blog/exploring-browser-rendering-process</a><p data-notion-block-id=\\"142e548d-8a8e-8053-8567-e66eb126d536\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#de888686-3d72-4003-8a20-e36af601960c\\">\uc608\uc804\uc5d0 \uac00\uc838\uc654\ub358 HTTP + DNS \uc124\uba85 \uae00</a>\uacfc \ube44\uc2b7\ud558\uc9c0\ub9cc, \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1\uc744 \uac04\ub7b5\ud558\uac8c \ucd94\uac00\ud55c \uae00\uc785\ub2c8\ub2e4. \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1\uc5d0 \ub354 \uae4a\uac8c \uc774\ud574\ud558\uba74 \uc88b\uc9c0\ub9cc, \ub300\ub7b5\uc801\uc73c\ub85c \uc0b4\ud3b4\ubcf4\uae30\uc5d0 \uc88b\ub124\uc694. \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uc2e4 \ubd84\uc740 <a href=\\"https://developer.chrome.com/blog/inside-browser-part3?hl=ko\\">web.dev\uc758 \ucd5c\uc2e0 \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1 \uac1c\uc694</a>\ub098 <a href=\\"https://developer.chrome.com/docs/chromium/renderingng-architecture\\">Chrome blog\uc758 RenderingNG \uc544\ud0a4\ud14d\uccd0 \uac1c\uc694</a>\ub97c \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"142e548d-8a8e-8081-83ba-e1d1de4dd6ba\\" id=\\"142e548d-8a8e-8081-83ba-e1d1de4dd6ba\\"><code>outline</code>\uc744 \uc608\uc058\uac8c \ub9cc\ub4e4\uae30</h2><a href=\\"https://medienbaecker.com/articles/focus-outlines\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medienbaecker.com/articles/focus-outlines</a><p data-notion-block-id=\\"142e548d-8a8e-80f0-a469-e6701a8478cb\\">\uacbd\uc6b0\uc5d0 \ub530\ub77c \ub514\uc790\uc774\ub108\uac00 <code>outline: none;</code>\ub97c \uc801\uc6a9\ud574\ub2ec\ub77c\uace0 \uc81c\uc548\ud560 \uacbd\uc6b0\ub3c4 \uc788\ub294\ub370, \uc811\uadfc\uc131\uacfc \uc0ac\uc6a9\uc790 \uacbd\ud5d8\uc5d0 \ub098\uc05c \uc601\ud5a5\uc744 \ub07c\uce69\ub2c8\ub2e4. \uadf8\ub798\uc11c <code>outline</code>\uc744 \uc774\uc058\uac8c \ub9cc\ub4dc\ub294 \ud301\uc744 \uc81c\uacf5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uae00\uc5d0\uc11c\ub294 <code>outline</code>\uc744 \uc798 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud588\uc9c0\ub9cc, \uc5ec\ub7ec\uac00\uc9c0 CSS \ubb38\ubc95\ub4e4\uc740 \ub2e4\ub978 \uacf3\uc5d0\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\uc73c\ub2c8 \uc775\ud600\ubcf4\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"145e548d-8a8e-80e2-86c5-d0569cc472b5\\" id=\\"145e548d-8a8e-80e2-86c5-d0569cc472b5\\"><code>dangerouslySetInnerHTML</code>\uc740 \uc704\ud5d8\ud558\ub2e4.</h2><a href=\\"https://macarthur.me/posts/safer-dangerouslysetinnerhtml/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://macarthur.me/posts/safer-dangerouslysetinnerhtml/</a><p data-notion-block-id=\\"145e548d-8a8e-8043-ac05-eb3c3a35c861\\">React\uc758 <code>dangerouslySetInnerHTML</code>\uc744 \ud1b5\ud574 \uc2a4\ud06c\ub9bd\ud2b8\ub97c \uc2e4\ud589\ud560 \uc218\ub3c4 \uc788\uace0, XSS \ucde8\uc57d\uc810\uc774 \uc0dd\uae38 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uae00\uc5d0\uc11c\ub294<a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/CSP\\"> CSP \uc124\uc815</a>\uc774\ub098 DOM \ud30c\uc11c, \uc704\ud5d8 \uc18d\uc131/\ud0dc\uadf8 \uc0ad\uc81c\ub97c \ud574\uacb0\ucc45\uc73c\ub85c \uc81c\uc2dc\ud569\ub2c8\ub2e4. \uacbd\uc6b0\uc5d0 \ub530\ub77c DOM purifier\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\ub3c4 \ubc29\ubc95\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"142e548d-8a8e-8032-b99c-cf63e1995ac3\\" id=\\"142e548d-8a8e-8032-b99c-cf63e1995ac3\\">View Transition \ub9c8\uc2a4\ud130\ud558\uae30</h2><a href=\\"https://www.debugbear.com/blog/view-transitions-spa-without-framework\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/view-transitions-spa-without-framework</a><p data-notion-block-id=\\"142e548d-8a8e-801e-8d2b-c7fada5b3053\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/022fc2c2-88d3-4c20-9075-defdea8ae65c#573e1373-8623-4b1c-8d62-eb4359347395\\">View Transition</a> \uc18c\uac1c, \uc791\ub3d9 \ubc29\uc2dd, \ubc14\ub2d0\ub77c JS\uc5d0\uc11c \uc0ac\uc6a9\ud574\ubcf4\ub294 \uc608\uc81c\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc544\uc9c1 \uc548\ucc29\ub41c \uae30\uc220\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc5b4\ub5a4 \uae30\uc220\uc778\uc9c0, \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uc9c0\ub294 \ubbf8\ub9ac \uc0b4\ud3b4\ubcfc\ub9cc \ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"145e548d-8a8e-8025-b137-f7a6b1ba4629\\" id=\\"145e548d-8a8e-8025-b137-f7a6b1ba4629\\">\uba85\ub839\ud615\uacfc \uc120\uc5b8\ud615.</h2><a href=\\"https://ui.dev/c/react/imperative-vs-declarative\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ui.dev/c/react/imperative-vs-declarative</a><p data-notion-block-id=\\"145e548d-8a8e-802c-9c76-d784b7a4b4d5\\">\uba85\ub839\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uacfc \uc120\uc5b8\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uc744 \ud604\uc2e4\uc758 \uc608\uc640 \uc2e4\uc81c \ucf54\ub4dc\ub97c \ud1b5\ud574 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"145e548d-8a8e-8081-a657-e371e3a94cc2\\" id=\\"145e548d-8a8e-8081-a657-e371e3a94cc2\\">CSS \uc804\ub7b5 \uc18c\uac1c</h2><a href=\\"https://thetshaped.dev/p/the-styling-dilemma-in-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://thetshaped.dev/p/the-styling-dilemma-in-react</a><p data-notion-block-id=\\"145e548d-8a8e-8045-a7d0-d56c021f089a\\">\ubaa8\ub4e0 CSS \uae30\ubc18 \uc2a4\ud0c0\uc77c\ub9c1 \ubc29\ubc95(\ubc14\ub2d0\ub77c\ubd80\ud130 \ub2e4\uc591\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac)\uc744 \uac00\ubccd\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 \uac1d\uad00\uc801\uc774\uace0 \uae4a\uace0 \ub113\uc740 \uc5ed\uc0ac\uc5d0 \ub300\ud574 \uc0b4\ud3b4\ubcf4\uc2e4 \ubd84\uc740 <a href=\\"https://frontendmastery.com/posts/the-evolution-of-scalable-css/\\">frontendmastery\uc758 \ud655\uc7a5 \uac00\ub2a5\ud55c CSS</a>\uc758 \uc5ed\uc0ac\ub97c \ubcf4\uc138\uc694. \ub2e4\ub978 \uad00\uc810\uc73c\ub85c \uc0b4\ud3b4\ubcf4\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/6631ddbe-1279-426c-88c7-e9e02785bbb6#12c2ec72-b604-413e-89e5-a73e42245485\\">CSS \ucd5c\uc2e0 \ub3c4\uad6c\ub4e4</a> \uae00\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"142e548d-8a8e-8082-bce8-f572cbfd81b9\\" id=\\"142e548d-8a8e-8082-bce8-f572cbfd81b9\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://ishadeed.com/article/overflow-clip/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/overflow-clip/</a><a href=\\"https://socket.dev/blog/vlt-debuts-new-javascript-package-manager-and-serverless-registry\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://socket.dev/blog/vlt-debuts-new-javascript-package-manager-and-serverless-registry</a><p data-notion-block-id=\\"142e548d-8a8e-80f5-a0a6-c6512c23c1fd\\">\uccab\ubc88\uc9f8 \uae00\uc740 \ube44\uad50\uc801 \ucd5c\uadfc\uc5d0 \ucd94\uac00\ub41c <code>overflow: clip;</code>\uc744 \uc18c\uac1c\ud558\uace0 \uc0ac\uc6a9\ud558\ub294 \uacf3\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774\uace0, \ub450\ubc88\uc9f8 \uae00\uc740 \uc0c8\ub85c\uc6b4 \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\uc778 vlt\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc544\uc9c1 \uc758\uc874\uc131 \uac80\uc0c9 \ubc0f \uadf8\ub798\ud504 \uc0dd\uc131 \uc678\uc5d0 \ub2e4\ub978 \uae30\ub2a5\uc774 \uc5c6\uc5b4\ubcf4\uc774\uc9c0\ub9cc, npm\uc744 \ub9cc\ub4e4\ub358 \uc0ac\ub78c\uc774 <a href=\\"https://blog.vlt.sh/blog/the-massive-hole-in-the-npm-ecosystem\\">npm \uc0dd\ud0dc\uacc4\uc758 \ubc84\uadf8\ub4e4\uacfc \ucde8\uc57d\uc810\uc744 \ud574\uacb0\ud558\uc9c0 \ubabb\ud55c \uac83\uc744 \ubcf4\uace0</a> \uc0c8\ub85c\uc6b4 \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\ub97c \ub9cc\ub4e4\uc5c8\uc73c\ub2c8 \uc9c0\ucf1c \ubcfc \ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p>"}')}}]);